    "name",
    "kind",
    "inputs"
   ],
   "title": "EndStep",
   "type": "object"
  },
  "ExecutionStep": {
   "additionalProperties": false,
   "properties": {
    "name": {
     "description": "Short kebab-case identifier, unique within the procedure. Edges (`inputs_to`, router `branches`) reference steps by this name.",
     "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
     "title": "Name",
     "type": "string"
    },
    "kind": {
     "const": "execution",
     "description": "A script runs. Analogous to a tool call.",
     "title": "Kind",
     "type": "string"
    },
    "description": {
     "description": "What the script does. One line; the script is the source of truth.",
     "title": "Description",
     "type": "string"
