        def quantize(v):
            return (round(v[0], 5), round(v[1], 5), round(v[2], 5))

        n = len(self.triangles)
        parent = list(range(n))

        def find(i):
            while parent[i] != i:
                parent[i] = parent[parent[i]]
                i = parent[i]
            return i

